css:
.fx-hot{width:min(760px,100%);position:relative}
.fx-hot .scene{position:relative;aspect-ratio:16/10;border-radius:var(--radius);overflow:hidden}
.fx-hot .scene .fx-art{position:absolute;inset:0;border-radius:0}
.fx-hot .pin{position:absolute;translate:-50% -50%}
.fx-hot .pin>button{width:2.2em;height:2.2em;border-radius:50%;border:2px solid var(--on-accent);background:var(--accent);color:var(--on-accent);font:700 .85em var(--font-body);cursor:pointer;box-shadow:0 0 0 0 color-mix(in srgb,var(--accent) 60%,transparent);animation:fx-hot-p 2.4s infinite}
.fx-hot .pin>button[aria-expanded=true]{animation:none;background:var(--surface);color:var(--text);border-color:var(--accent)}
@keyframes fx-hot-p{70%{box-shadow:0 0 0 .9em transparent}}
.fx-hot .pop{position:absolute;left:50%;top:calc(100% + .7em);translate:-50% 0;width:13em;background:var(--surface);color:var(--text);border-radius:var(--radius);box-shadow:0 12px 30px color-mix(in srgb,#000 22%,transparent);padding:.8em;display:none;z-index:4;font-size:.9em}
.fx-hot .pin.up .pop{top:auto;bottom:calc(100% + .7em)}
.fx-hot .pin>button[aria-expanded=true]+.pop{display:block}
.fx-hot .pop b{display:block}.fx-hot .pop span{opacity:.7}.fx-hot .pop a{display:inline-block;margin-top:.5em;color:var(--primary);font-weight:700}
@media(prefers-reduced-motion:reduce){.fx-hot .pin>button{animation:none}}
